```json
{
  "type": "auth.hello",
  "id": "01HXYZ...",
  "ts": "...",
  "cid": null,
  "payload": {
    "device": {
      "id": "dev_01HXYZ...",
      "kind": "mobile" | "web" | "desktop" | "embedded" | "server",
      "platform": "ios" | "android" | "browser-chrome-122" | "linux-x86_64" | ...,
